package com.aaliyun.leadnews.article.web;
import com.aaliyun.leadnews.article.service.HotArticleQueryService;import com.aaliyun.leadnews.common.api.ResponseResult;import com.aaliyun.leadnews.model.hot.HotArticleResponse;import jakarta.validation.constraints.*;import org.springframework.validation.annotation.Validated;import org.springframework.web.bind.annotation.*;
@Validated @RestController @RequestMapping("/api/article") public class HotArticleController {private final HotArticleQueryService hot;public HotArticleController(HotArticleQueryService h){hot=h;}@GetMapping("/hot")public ResponseResult<HotArticleResponse> hot(@RequestParam(required=false)Long channelId,@RequestParam(defaultValue="20")@Min(1)@Max(50)int limit){return ResponseResult.success(hot.hot(channelId,limit));}}
